class NativeRuntimeCapabilitiesTest(unittest.TestCase):
 def test_exact_sdk_readers_owner_lifecycle_and_existing_audit_freshness(self):
  java=os.environ.get('PROFILE_JAVA') or shutil.which('java');self.assertTrue(java,'Real JDK required; no skipped acceptance')
  spec=importlib.util.spec_from_file_location('runtime_capabilities_member_reader',ROOT/'tests/page-recovery-host/run.py');reader=importlib.util.module_from_spec(spec);spec.loader.exec_module(reader)
  web=(SOURCE/'GeckoWebView.java').read_text();audit=(SOURCE/'EnvironmentAudit.java').read_text();host=HOST.read_text();host=host.replace('/* NATIVE_OWNER */','\n'.join(reader.member(web,n) for n in ['Object nativeRuntimeIdentity(','JSONObject nativeRuntimeCapabilities(']));host=host.replace('/* AUDIT_FRESH */',reader.member(audit,'boolean fresh('));host=host.replace('/* AUDIT_EXPECTED */',reader.member(audit,'JSONObject expected('));host=host.replace('/* AUDIT_LOCAL_EXPECTED */',reader.member(audit,'JSONObject localExpected('));host=host.replace('/* AUDIT_CLEANUP */',reader.member(audit,'void cleanup('));host=host.replace('import java.util.*;','import java.util.*;import android.os.Build;')
  inputs=[SOURCE/'GeckoPolicyAdapter.java',SOURCE/'GeckoWebView.java',SOURCE/'EnvironmentAudit.java',SOURCE/'J.java',HOST,Path(__file__)];before={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in inputs};runs=[]
  for name,env,default in [('desktop','PROFILE_JSON_JAR','json.jar'),('android-json','PROFILE_ANDROID_JSON_JAR','android-json.jar')]:
   jar=Path(os.environ.get(env,ROOT/'work/profile-host'/default));self.assertTrue(jar.is_file(),'Pinned JSON jar required: '+str(jar));self.assertEqual(hashlib.sha256(jar.read_bytes()).hexdigest(),PINS[name])
   with tempfile.TemporaryDirectory(prefix='native-runtime-capabilities-host-') as d:
    d=Path(d);sources=[]
    for path,text in STUBS.items():
     p=d/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text);sources.append(p)
    p=d/'local/pocketchat/NativeRuntimeCapabilitiesHost.java';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(host);sources += [p,SOURCE/'GeckoPolicyAdapter.java',SOURCE/'J.java']
    built=subprocess.run([java,'-m','jdk.compiler/com.sun.tools.javac.Main','--release','8','-encoding','UTF-8','-cp',str(jar),'-d',str(d),*map(str,sources)],capture_output=True,text=True,timeout=40);self.assertEqual(built.returncode,0,built.stdout+built.stderr)
    result=subprocess.run([java,'-cp',str(d)+os.pathsep+str(jar),'local.pocketchat.NativeRuntimeCapabilitiesHost'],capture_output=True,text=True,timeout=20);self.assertEqual(result.returncode,0,result.stdout+result.stderr);report=json.loads(result.stdout);self.assertEqual(report['status'],'passed');self.assertGreaterEqual(report['checks'],40);self.assertEqual(report['checks'],len(report['results']));self.assertTrue(all(x['pass'] is True for x in report['results']));self.assertEqual(len({x['name'] for x in report['results']}),report['checks'])
    for flag in ['actualAndroidExecution','actualGeckoExecution','actualSdkApiCompile','physicalPhoneAcceptance','sandboxAcceptance']:self.assertIs(report[flag],False)
    runs.append({'runtime':name,'report':report})
  self.assertEqual(before,{str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in inputs});out=ROOT/'work/native-runtime-capabilities/host-results.json';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps({'status':'passed','sourceSha256':before,'runs':runs,'actualSdkApiCompile':False,'actualAndroidExecution':False,'physicalPhoneAcceptance':False},ensure_ascii=False,indent=2)+'\n')
